import { GameClient, mergeCorrections, type GameClientOptions, type GamePredictionOptions } from '@hops-ops/distributed/game';

import { EVENTS, type Events } from './events.ts';
import { encodeInput, type MoveInput } from './input.ts';
import { CORRECTIONS } from './schema.ts';

/** Prediction options; `encodeInput` and the correction defaults are filled in. */
export type GridPredictionOptions = Omit<GamePredictionOptions<MoveInput>, 'encodeInput'> &
	Partial<Pick<GamePredictionOptions<MoveInput>, 'encodeInput'>>;

export type GridClientOptions = Omit<GameClientOptions<MoveInput>, 'prediction'> &
	Readonly<{ prediction?: GridPredictionOptions }>;

export type GridClient = Readonly<{
	client: GameClient<MoveInput>;
	/** Typed event subscription (every zone); returns the unsubscribe. */
	on<K extends keyof Events>(name: K, handler: (value: Events[K], zoneId: string) => void): () => void;
	/** Send one input: predicted when prediction is configured, raw otherwise. */
	send(input: MoveInput): number | undefined;
}>;

/** A `GameClient` for the `grid` surface with its input encoder and correction defaults. */
export function createGridClient(options: GridClientOptions): GridClient {
	const prediction = options.prediction;
	const client = new GameClient<MoveInput>({
		...options,
		prediction:
			prediction === undefined
				? undefined
				: {
						...prediction,
						encodeInput: prediction.encodeInput ?? ((input) => encodeInput(input)),
						corrections: mergeCorrections(CORRECTIONS, prediction.corrections)
					}
	});
	return {
		client,
		on: (name, handler) =>
			client.on('event', (zoneId, event) => {
				const codec = EVENTS[name];
				if (event.typeId === codec.id) handler(codec.decode(event.payload), zoneId);
			}),
		send: (input) =>
			prediction === undefined ? client.sendRawInput(encodeInput(input)) : client.sendInput(input)
	};
}
